function sync(){const u=new URL(location.href);u.searchParams.set("perfil",profile);u.searchParams.set("reto",active);history.replaceState(null,"",u);}
function updateProfile(){const p=profiles[profile];$("role-picker").value=profile;$("role-desc").textContent=p[1];$("role-count").textContent=p[2].length+" herramientas recomendadas";renderMenu();}
function renderMenu(){const p=profiles[profile];let sequence=0;const mobile=$("mobile-tools");mobile.replaceChildren();$("menu").replaceChildren();for(const g of ["Control de operaciones","Planificación y optimización","Fiabilidad y servicio","Rentabilidad y costes","Automatización y control"]){const list=cases.filter(c=>c[1]===g&&p[2].includes(c[0]));if(!list.length)continue;const el=document.createElement("p");el.className="group";el.textContent=g;$("menu").append(el);for(const c of list){const b=document.createElement("button");b.className="navcase";b.dataset.case=c[0];b.setAttribute("aria-current",String(c[0]===active));b.innerHTML='<span class="num">'+String(++sequence).padStart(2,"0")+'</span><span>'+esc(c[2])+'</span>';b.onclick=()=>select(c[0],true);$("menu").append(b);const o=document.createElement("option");o.value=c[0];o.textContent=String(sequence).padStart(2,"0")+" · "+c[2];mobile.append(o);}}}
function clearAssistant(){askToken++;proposal=null;const a=$("assistant-answer");if(a)a.replaceChildren();const b=$("ask-process");if(b)b.disabled=false;}
function render(values=getv()){if(mapInstance){mapInstance.remove();mapInstance=null;}mapState=null;const [m,v,action,method]=renderers[active](values);executed=values.slice();lastResult={action,method};$("results").innerHTML=m+'<div class="viz">'+v+'</div><section class="next"><h3>Decisión que habilita</h3><p>'+esc(action)+'</p></section><details class="details"><summary>Datos y límites del ejemplo</summary><p>'+esc(method)+'</p></details>';bindMap();bindForecast();$("results").setAttribute("aria-busy","false");setStatus("Resultados actualizados · datos sintéticos","done");clearAssistant();}
async function execute(){const token=++runToken,id=active,g=guides[id],values=getv().slice(),b=$("run-model");if(!b)return;b.disabled=true;clearAssistant();$("results").setAttribute("aria-busy","true");for(const [i,s] of ["Preparar datos y parámetros",g[4],g[5]].entries()){setStatus((i+1)+"/3 · "+s+"…","loading");await wait(500);if(token!==runToken||id!==active)return;}render(values);b.disabled=false;if(dirty())setStatus("Cambios pendientes · ejecutar de nuevo.","pending");}
function instant(id,i){return !explicit.has(id)||(id==="demanda"&&[2,4].includes(i))||(id==="retrasos"&&[0,1,2,4].includes(i))||(id==="documentos"&&i===0);}
function onInput(e){const i=Number(e.dataset.input),out=$("val"+i);if(out)out.textContent=e.value;state[active]=getv();clearAssistant();runToken++;if($("run-model"))$("run-model").disabled=false;$("results").setAttribute("aria-busy","false");if(!instant(active,i)){setStatus("Cambios pendientes · ejecuta el modelo para actualizar resultados.","pending");return;}const v=explicit.has(active)?executed.map((x,j)=>i===j?getv()[i]:x):getv();render(v);if(dirty())setStatus("Otros parámetros pendientes de ejecutar.","pending");}
function assistantHTML(){return '<section class="assistant"><div class="assistant-top"><span class="assistant-mark" aria-hidden="true">✦</span><div><p class="kicker">ASISTENTE DE PROCESOS</p><h3>Pregúntale a tu operación</h3><p>Interpreta el resultado, descubre la integración o ensaya un cambio.</p></div></div><div class="quick-questions"><button data-question="explain" type="button">¿Qué significa este resultado?</button><button data-question="process" type="button">¿Cómo lo integraríamos?</button><button data-question="change" type="button">¿Qué parámetro puedo probar?</button></div><form id="assistant-form"><label for="assistant-input">Pregunta sobre esta herramienta</label><div class="ask-row"><input id="assistant-input" maxlength="240" placeholder="Ej.: ¿Qué datos necesitaríamos?"><button type="submit" id="ask-process">Preguntar →</button></div></form><div id="assistant-answer" aria-live="polite"></div><p class="source">Asistente simulado mediante reglas y resultados locales. No utiliza un LLM ni realiza acciones externas.</p></section>';}
function classify(q){const s=q.toLowerCase();if(/cambi|probar|parámetr|parametr|aument|reduc|simul|optimi/.test(s))return "change";if(/integra|empresa|proceso|datos|implement|automat|tms|erp|wms/.test(s))return "process";if(/significa|explica|resultado|gráfico|grafico|riesgo|indicador|interpre/.test(s))return "explain";return "unknown";}
async function ask(q,kind=classify(q)){const token=++askToken,id=active,g=guides[id],c=cases.find(x=>x[0]===id),out=$("assistant-answer");proposal=null;$("ask-process").disabled=true;out.innerHTML='<div class="assistant-thinking">Consultando el resultado y el proceso actual…</div>';await wait(700);if(token!==askToken||id!==active)return;$("ask-process").disabled=false;let a="";
if(kind==="explain"){const metrics=[...$("results").querySelectorAll(".metric")].map(el=>el.querySelector("small").textContent+": "+el.querySelector("strong").textContent);a='<h4>Interpretación del último cálculo</h4>'+metrics.map(s=>'<span class="assistant-metric">'+esc(s)+'</span>').join("")+'<p>'+esc(g[3])+'</p><p><strong>Decisión:</strong> '+esc(lastResult.action)+'</p>';}
else if(kind==="process"){a='<h4>Cómo se implementaría</h4><p>'+esc(c[4])+'</p><ol><li><strong>Datos:</strong> '+esc(c[5])+'</li><li><strong>Cálculo:</strong> '+esc(g[4])+'</li><li><strong>Validación:</strong> contrastar resultados y restricciones con el responsable del proceso.</li><li><strong>Operación:</strong> '+esc(lastResult.action)+'</li></ol><p>Las acciones externas requerirían permisos y aprobación según el proceso real.</p>';}
else if(kind==="change"){const i=g[6],d=defs[id][i],old=getv()[i];let alt=g[7];if(alt===old)alt=d[0]==="select"?(old+1)%d[2].length:old===d[3]?d[2]:d[3];alt=d[0]==="select"?clamp(alt,0,d[2].length-1):clamp(alt,d[2],d[3]);proposal={id,i,alt};const show=v=>d[0]==="select"?d[2][v]:v;a='<h4>Propuesta de prueba</h4><p>Modificar <strong>'+esc(d[1])+'</strong>: '+esc(show(old))+' → '+esc(show(alt))+'. No se aplicará hasta que confirmes.</p><div class="proposal-actions"><button id="apply-proposal" type="button">Aplicar y comprobar</button><button id="cancel-proposal" type="button">Cancelar</button></div>';}
else a='<p>Esta simulación responde a consultas sobre indicadores, integración y cambios de parámetros. Prueba las preguntas sugeridas.</p>';
out.innerHTML='<div class="assistant-reply">'+a+(dirty()?'<p class="source">Hay parámetros pendientes. La explicación utiliza el último resultado calculado.</p>':'')+'</div>';
if(proposal){$("apply-proposal").onclick=()=>{const p=proposal;if(!p||p.id!==active)return;const e=document.querySelector('[data-input="'+p.i+'"]');e.value=p.alt;const output=$("val"+p.i);if(output)output.textContent=e.value;state[active]=getv();clearAssistant();if(explicit.has(active))execute();else render();};$("cancel-proposal").onclick=()=>{proposal=null;out.textContent="Propuesta descartada. No se ha modificado nada.";};}}
function select(id,scroll=false){runToken++;askToken++;if(mapInstance){mapInstance.remove();mapInstance=null;}if(!Object.hasOwn(renderers,id))id=profiles[profile][3];if(!profiles[profile][2].includes(id)){profile="all";updateProfile();}active=id;$("mobile-tools").value=id;const c=cases.find(x=>x[0]===id),g=guides[id],run=explicit.has(id),a=actionGuides[id];document.querySelectorAll(".navcase").forEach(b=>b.setAttribute("aria-current",String(b.dataset.case===id)));
$("case").innerHTML='<div class="case-head"><span class="type-label" data-type="'+esc(g[0])+'">'+esc(g[0])+'</span><h2>'+esc(c[2])+'</h2><p class="lead">'+esc(c[3])+'</p><p class="business-question">'+esc(g[1])+'</p></div><section class="try-guide action-guide"><div class="action-heading"><span class="action-icon" aria-hidden="true">↗</span><div><span class="action-eyebrow">PRUÉBALO TÚ MISMO</span><h3>'+esc(a[0])+'</h3><p>'+esc(a[2])+'</p></div></div><div class="action-buttons"><button id="try-preset" type="button" class="try-primary">'+esc(a[1])+' →</button><button id="try-manual" type="button" class="try-secondary">Personalizar parámetros ↓</button></div><div id="try-feedback" class="try-feedback" role="status"></div></section><section class="work"><div class="worktop"><div><h3>'+esc(c[6])+'</h3><p>'+esc(c[7])+'</p></div><span class="mode">'+(run?"Modelo bajo demanda":"Actualización inmediata")+'</span></div><div class="filter" id="tool-parameters">'+controls(id)+'</div><div class="execution">'+(run?'<button id="run-model" class="execute-btn" type="button">'+esc(labels[id])+' →</button>':'')+'<span id="execution-status" role="status" class="exec-status"></span></div><div class="read-guide"><strong>Qué estás viendo · cómo decidir</strong><p>'+esc(a[3])+'</p></div><div id="results"></div></section>'+assistantHTML()+'<details class="approach-detail"><summary>Diseño a medida · solución, datos y métodos cuantitativos</summary><div class="approach"><section><h3>Solución</h3><p>'+esc(c[4])+'</p></section><section><h3>Datos</h3><p>'+esc(c[5])+'</p></section><section class="method-span"><h3>'+esc(methods[id][0])+'</h3><p>'+esc(methods[id][1])+'</p><p class="source">Métodos candidatos para una implementación personalizada; la demo no implementa necesariamente todos ellos.</p></section></div></details><p class="source">Datos sintéticos; la implementación requiere validación con los datos de tu operación.</p>';
document.querySelectorAll("[data-input]").forEach(e=>{if(state[id]?.[e.dataset.input]!==undefined)e.value=state[id][e.dataset.input];const out=$("val"+e.dataset.input);if(out)out.textContent=e.value;e.addEventListener("input",()=>onInput(e));});$("try-preset").onclick=()=>{const e=[...document.querySelectorAll("[data-input]")].find(e=>Number(e.dataset.input)===a[4]);if(!e)return;e.value=a[5];onInput(e);$("try-feedback").textContent="Prueba aplicada: "+a[1]+". "+(run&&!instant(id,a[4])?"Calculando el resultado…":"Resultado actualizado.");if(run&&!instant(id,a[4]))execute();};$("try-manual").onclick=()=>{$("tool-parameters").scrollIntoView({block:"center",behavior:"smooth"});$("tool-parameters").querySelector("select,input")?.focus({preventScroll:true});};if(run)$("run-model").onclick=execute;$("assistant-form").onsubmit=e=>{e.preventDefault();const q=$("assistant-input").value.trim();if(q)ask(q);};document.querySelectorAll("[data-question]").forEach(b=>b.onclick=()=>ask(b.textContent,b.dataset.question));sync();render();if(scroll)$("case").scrollIntoView({block:"start",behavior:"smooth"});}
$("mobile-tools").onchange=e=>select(e.target.value,true);const picker=$("role-picker");Object.entries(profiles).forEach(([id,p])=>{const o=document.createElement("option");o.value=id;o.textContent=p[0];picker.append(o);});picker.onchange=()=>{profile=picker.value;updateProfile();select(profiles[profile][3],true);};updateProfile();select(query.get("reto")||profiles[profile][3]);
